SELECT ca.*,
       co.course_name,
       co.credit,
       t.name AS teacher_name,
       c.class_name
FROM course_arrangement ca
LEFT JOIN course co ON ca.course_id = co.id
LEFT JOIN teacher t ON ca.teacher_id = t.id
LEFT JOIN class c ON ca.class_id = c.id


        AND ca.course_id = #{courseId}


        AND ca.teacher_id = #{teacherId}


        AND ca.class_id = #{classId}


        AND ca.semester = #{semester}


        AND ca.status = #{status}


ORDER BY ca.create_time DESC

